From fc1b0cca5d506f3a969d98802fff1d6d9d43ffdc Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 00:58:47 +0100
Subject: [PATCH] ConnectionSettings: use SAE for WPA3-only Wi-Fi codes

WPA3 Wi-Fi codes use T:WPA and mark SAE-only networks with bit 0 of the
hex R (transition disable) field. fromMeCard ignored it and set up
WPA-PSK, which such networks refuse, so use SAE when that bit is set.

BUG: 526296
---
 src/settings/connectionsettings.cpp | 7 +++++--
 1 file changed, 5 insertions(+), 2 deletions(-)

diff --git a/src/settings/connectionsettings.cpp b/src/settings/connectionsettings.cpp
index d76a7d2..fbd6ff2 100644
--- a/src/settings/connectionsettings.cpp
+++ b/src/settings/connectionsettings.cpp
@@ -666,11 +666,14 @@ void NetworkManager::ConnectionSettings::fromMeCard(const QVariantMap &map)
         wifiSecurity->setInitialized(true);
     }

-    if (securityType == QLatin1String("WPA") || securityType == QLatin1String("WEP")) {
+    // WPA3 spec: R is a hex Transition Disable value, bit 0 set means the network is WPA3-SAE only
+    const bool saeOnly = map.value(QLatin1String("R")).toString().toUInt(nullptr, 16) & 1;
+
+    if ((securityType == QLatin1String("WPA") && !saeOnly) || securityType == QLatin1String("WEP")) {
         wifiSecurity->setKeyMgmt(NetworkManager::WirelessSecuritySetting::WpaPsk);
         wifiSecurity->setPsk(map.value(QLatin1String("P")).toString());
         wifiSecurity->setPskFlags(NetworkManager::Setting::AgentOwned);
-    } else if (securityType == QLatin1String("SAE")) {
+    } else if (securityType == QLatin1String("SAE") || securityType == QLatin1String("WPA")) {
         wifiSecurity->setKeyMgmt(NetworkManager::WirelessSecuritySetting::SAE);
         wifiSecurity->setPsk(map.value(QLatin1String("P")).toString());
         wifiSecurity->setPskFlags(NetworkManager::Setting::AgentOwned);
